          (input)="limit.set(value($event)); limitChanged = true; settingsError.set(null)"
          (keydown)="limitChanged = true"
        />
        <span>
          In force: <span data-testid="setting-clerk-limit-current">{{ clerkLimit() ?? '' }}</span>
          @if (clerkLimit() === null) {
            (no limit)
